mapper.select:
select
from pro_trans_consume c
c.del_flag = '0' and c.record_id = #{recordId}

select
,
t.task_code, t.process_code, t.process_name,
w.workorder_code, w.product_name,
ws.workstation_code, ws.workstation_name
from pro_trans_consume c


    c.del_flag = '0'

        and c.task_id = #{taskId}


        and c.workorder_id = #{workorderId}


        and c.process_id = #{processId}


        and c.workstation_id = #{workstationId}


        and c.item_id = #{itemId}


        and c.item_code like concat('%', #{itemCode}, '%')


        and c.item_name like concat('%', #{itemName}, '%')


        and c.trans_order_code like concat('%', #{transOrderCode}, '%')


        and c.batch_code like concat('%', #{batchCode}, '%')


        and w.workorder_code like concat('%', #{workorderCode}, '%')


        and t.task_code like concat('%', #{taskCode}, '%')


        and c.consume_date >= #{consumeDateFrom}


        and c.consume_date <= #{consumeDateTo}


order by c.record_id desc

select , t.task_code, t.process_code, t.process_name, w.workorder_code, w.product_name, ws.workstation_code, ws.workstation_name from pro_trans_consume c
c.del_flag = '0' and c.task_id = #{taskId}
order by c.record_id asc

select , t.task_code, t.process_code, t.process_name, w.workorder_code, w.product_name, ws.workstation_code, ws.workstation_name from pro_trans_consume c
c.del_flag = '0' and c.workorder_id = #{workorderId}
order by c.task_id asc, c.record_id asc

select c.item_id, c.item_code, c.item_name, c.specification, c.unit_of_measure, sum(c.quantity_consumed) as quantity_consumed from pro_trans_consume c
c.del_flag = '0' and c.workorder_id = #{workorderId}
group by c.item_id, c.item_code, c.item_name, c.specification, c.unit_of_measure order by c.item_code asc

select ifnull(sum(quantity_consumed), 0)
from pro_trans_consume
where del_flag = '0'
  and task_id = #{taskId}
  and item_id = #{itemId}

select b.item_id, b.item_code, b.item_name, b.specification, b.unit_of_measure, b.unit_name, b.quantity as unit_qty, round(b.quantity * #{taskQty}, 6) as plan_qty, ifnull(c.consumed_qty, 0) as consumed_qty, round(ifnull(c.consumed_qty, 0) - b.quantity * #{taskQty}, 6) as diff_qty, case when ifnull(c.consumed_qty, 0) > b.quantity * #{taskQty} then 1 else 0 end as over_flag from pro_route_product_bom b left join ( select item_id, sum(quantity_consumed) as consumed_qty from pro_trans_consume where del_flag = '0' and task_id = #{taskId} group by item_id ) c on c.item_id = b.item_id
b.del_flag = '0' and b.route_id = #{routeId} and b.process_id = #{processId} and b.product_id = #{productId}
order by b.item_code asc
